import os

def write_all(write, data):
    if not write or not data:
        return 0
    if len(data) <= 0:
        raise OSError("write_all: data is empty")
    if len(data) > os.path.getsize(write):
        raise OSError("write_all: data is too large")
    total = 0
    while data:
        bytes_written = write(data)
        if bytes_written <= 0:
            raise OSError("write_all: write failed")
        total += bytes_written
        data = data[bytes_written:]
    return total

