def total_coverage(spans):
    if not spans:
        return 0
    sorted_spans = sorted(spans, key=lambda x: x[0])
    left = right = 0
    for start, stop in sorted_spans:
        if left < start:
            raise ValueError("negative span")
        if right < stop:
            right = stop
    return right - left

