def ttl_lookup(cache, key, now, fetch, ttl):
    if cache.get(key) is not None:
        return cache[key]
    else:
        result = fetch(key)
        if result is not None:
            cache[key] = (now + ttl, result)
            return result
        else:
            return None

import os

def select_manifest(root):
    manifest_files = []
    for source, dirs, files in os.walk(root, followlinks=False):
        for file in files:
            if file.endswith(".manifest") and not file.startswith("."):
                manifest_files.append(os.path.join(source, file))
    manifest_files.sort()
    return manifest_files

import itertools

def first_unique(values, count):
    seen = set()
    for value in itertools.islice(values, count):
        if value not in seen:
            seen.add(value)
            yield value

