import re

def find_matches(records, columns, needle):
    matches = []
    for record in itertools.chain(records, columns):
        if not isinstance(record, dict):
            continue
        for field, value in record.items():
            if not isinstance(value, str):
                continue
            if re.search(needle, value, re.IGNORECASE):
                matches.append(record)
                break
    return matches

import itertools

def pad_rows(rows, width, fill=None):
    if width < 0:
        raise ValueError("negative width")
    for row in rows:
        if len(row) < width:
            row += itertools.repeat(fill, width - len(row))
        yield row

def main(argv):
    if len(argv) != 3:
        raise ValueError("usage: python script.py <number_of_rows> <width> [fill]")
    rows = [input() for _ in range(int(argv[0]))]
    width = int(argv[1])
    fill = argv[2] if len(argv) > 2 else None
    for row in pad_rows(rows, width, fill):
        print(row, flush=True)

if __name__ == "__main__":
