import curses

def main(stdscr):
    stdscr.timeout(120)
    stdscr.keypad(True)
    height, width = stdscr.getmaxyx()
    grid = [[0 for _ in range(width)] for _ in range(height)]
    snake = [[height // 2, width // 2]]
    direction = (0, 0)
    food = (height // 2, width // 2)
    score = 0

    while True:
        stdscr.erase()
        for row in grid:
            stdscr.addnstr(0, 0, row, width)
        stdscr.addch(food[0], food[1], "+")
        for part in snake:
            stdscr.addch(part[0], part[1], "o")
        stdscr.refresh()

        key = stdscr.getch()
        if key == ord("q"):
            break
        elif key == ord("w") and (direction != (0, 1)):
            direction = (0, -1)
        elif key == ord("s") and (direction != (0, -1)):
            direction = (0, 1)
        elif key == ord("a") and (direction != (1, 0)):
            direction = (-1, 0)
        elif key == ord("d") and (direction != (-1, 0)):
            direction = (1, 0)

        head = (snake[0][0] + direction[0], snake[0][1] + direction[1])
        if head == food:
            score += 1
            food = (height // 2, width // 2)
        elif not (0 <= head[0] < height and 0 <= head[1] < width):
            break
        elif grid[head[0]][head[1]] == 1:
            break
        else:
            grid[snake[0][0]][snake[0][1]] = 0
            snake.pop(0)
            grid[head[0]][head[1]] = 1
            snake.insert(0, head)

if __name__ == "__main__":
    curses.wrapper(main)
